#!/usr/bin/env node
// Holds every `([validated by: <test name>](path#Lnn))` citation to the test it names.
//
// Usage:
//   node scripts/check-spec-anchor-names.mjs           # report, exit 1 on any finding
//   node scripts/check-spec-anchor-names.mjs --fix     # repoint each line from the name it carries
//
// A line number is the wrong thing to cite: inserting an import above a suite moves every test below
// it, and the citation silently lands on a different, still-valid declaration. The name is what the
// author meant, so the name is what the citation records and the line becomes a derived pointer this
// script repairs. The `#Lnn` stays because the lint rule and the coverage job both index by it, and a
// citation without one marks the whole file covered rather than one test.
import {readFileSync, writeFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import process from 'node:process';
import {dirname, join, normalize} from 'node:path';
import {root} from './lib/repo-root.mjs';

const CITATION = /\[validated by(?<label>: [^\]]*)?\]\((?<path>(?:\.\.\/)+[\w./-]+?)#L(?<line>\d+)\)/g;
// Any other href shape is refused rather than ignored: the coverage job resolves `./../x` and `/x`
// to the same file and counts them, while this gate and the drift check would never have read them.
const ANY_HREF = /\[validated by(?:: [^\]]*)?\]\((?<path>[^)#\s]+)#L\d+\)/g;
// `xit`, `xdescribe` and `.skip` declare a test that never runs, which validates nothing.
const DECLARATION = /^\s*(?:f?it|f?describe|test)\(\s*(['"`])((?:\\.|(?!\1).)*)\1/;
const SKIPPED = /^\s*(?:x(?:it|describe|test)|(?:it|describe|test)\.skip)\(\s*(['"`])((?:\\.|(?!\1).)*)\1/;
const TEST_FILE = /\.(?:test|spec)\.[cm]?[jt]sx?$/;

const cache = new Map();
const args = process.argv.slice(2);
const fix = args.includes('--fix');
const named = args.filter(arg => !arg.startsWith('--'));
const findings = [];
let checked = 0;
let repaired = 0;

for (const spec of named.length > 0 ? named : specs()) {
  const source = readFileSync(join(root, spec), 'utf8');
  const specDir = dirname(spec);
  let changed = false;

  for (const match of source.matchAll(ANY_HREF)) {
    if (!match.groups.path.startsWith('../')) {
      findings.push(`${spec}: href "${match.groups.path}" must be relative and start with ../`);
    }
  }

  const rewritten = source.replace(CITATION, (whole, label, path, line, ...rest) => {
    const groups = rest[rest.length - 1];
    const target = normalize(join(specDir, groups.path));
    if (!TEST_FILE.test(target)) return whole;

    checked += 1;
    const declarations = declarationsIn(target);
    if (declarations === null) {
      findings.push(`${spec}: ${groups.path} does not exist`);
      return whole;
    }

    const named = groups.label ? groups.label.slice(2) : null;
    const atLine = declarations.find(declaration => declaration.line === Number(groups.line));

    const skipped = declarations.find(d => d.skipped && (d.name === named || d.line === Number(groups.line)));
    if (skipped) {
      findings.push(`${spec}: cites "${skipped.name}" at ${groups.path}#L${skipped.line}, which is skipped and validates nothing`);
      return whole;
    }

    if (named === null) {
      if (!atLine) {
        findings.push(`${spec}: ${groups.path}#L${groups.line} is not a declaration, so no name can be read from it`);
        return whole;
      }
      if (nameIsAmbiguous(declarations, atLine.name)) {
        findings.push(ambiguity(spec, groups.path, atLine.name, declarations));
        return whole;
      }
      if (!fix) {
        findings.push(`${spec}: ${groups.path}#L${groups.line} carries no test name`);
        return whole;
      }
      return rewrite(atLine.name, groups.path, atLine.line);
    }

    // Checked before the line is consulted: a name that identifies two declarations is not an
    // identifier, and while the line happens to agree nothing would ever say so.
    if (nameIsAmbiguous(declarations, named)) {
      findings.push(ambiguity(spec, groups.path, named, declarations));
      return whole;
    }

    if (atLine && atLine.name === named) return whole;

    const [match] = declarations.filter(declaration => declaration.name === named);
    if (!match) {
      findings.push(`${spec}: names "${named}", which no declaration in ${groups.path} has`);
      return whole;
    }
    if (!fix) {
      findings.push(`${spec}: names "${named}" but points at #L${groups.line}; it is at #L${match.line}`);
      return whole;
    }
    return rewrite(named, groups.path, match.line);

    function rewrite(name, path, line) {
      // A name carrying a bracket would close the markdown label early: the citation stops being a
      // link, stops matching CITATION, and disappears from this gate and from the coverage job.
      if (/[[\]]/.test(name)) {
        findings.push(`${spec}: "${name}" carries a bracket and cannot be written into a markdown label`);
        return whole;
      }
      repaired += 1;
      changed = true;
      return citation(name, path, line);
    }
  });

  if (changed) writeFileSync(join(root, spec), rewritten);
}

for (const finding of findings) process.stderr.write(`check-spec-anchor-names: ${finding}\n`);

if (findings.length > 0) {
  process.stderr.write(`\ncheck-spec-anchor-names: ${findings.length} finding(s).\n`);
  process.stderr.write('Run `npm run spec:names -- --fix` to repoint a citation from the name it carries.\n');
  process.exit(1);
}

const verb = fix ? `repointed ${repaired},` : '';
process.stdout.write(`check-spec-anchor-names: ${verb} ${checked} citation(s) name the test they point at\n`);

function nameIsAmbiguous(declarations, name) {
  return declarations.filter(declaration => declaration.name === name && !declaration.skipped).length > 1;
}

function ambiguity(spec, path, name, declarations) {
  const lines = declarations.filter(declaration => declaration.name === name).map(d => `#L${d.line}`);
  return `${spec}: "${name}" names ${lines.length} declarations in ${path} (${lines.join(', ')}) — rename one`;
}

function citation(name, path, line) {
  return `[validated by: ${name}](${path}#L${line})`;
}

function declarationsIn(path) {
  if (cache.has(path)) return cache.get(path);

  let lines;
  try {
    lines = readFileSync(join(root, path), 'utf8').split('\n');
  } catch {
    cache.set(path, null);
    return null;
  }
  const found = lines.flatMap((text, index) => {
    const match = DECLARATION.exec(text);
    if (match) return [{line: index + 1, name: match[2], skipped: false}];
    const skipped = SKIPPED.exec(text);
    return skipped ? [{line: index + 1, name: skipped[2], skipped: true}] : [];
  });

  cache.set(path, found);
  return found;
}

function specs() {
  const out = execFileSync('git', ['ls-files', 'specs/**/*.md', 'adrs/*.md'], {cwd: root, encoding: 'utf8'});
  return out.trim().split('\n').filter(Boolean);
}
# Config-Installed Orchestrator Hooks

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#36 |
| Status | In Progress          |

`OrchestratorHooks` is the engine's only lifecycle seam, and `HalEngineConfig.orchestrator.hooks` is the supported way to install it: `createHalEngine` forwards the set to `createChatOrchestrator`, so a hook a deployer passes through the factory reaches the running orchestrator rather than sitting unread on the config object. This spec pins that forwarding and the measured semantics the seam already carries, so the hook-based features that follow in this epic — transparency disclosure, audit and usage recording, human oversight, provider failover — specify against real behaviour rather than against what the hook names suggest.

## Installing hooks through config

- A hook passed through `orchestrator.hooks` is forwarded to the orchestrator and fires ([validated by: forwards an orchestrator hook, so one passed through the config actually fires](../../src/config.test.ts#L19)).
- An engine built with no `orchestrator` key at all still processes a message, so the field is optional in fact and not only in the type ([validated by: processes a message when the config declares no orchestrator key at all](../../src/config.test.ts#L95)).
- A `beforeModelResponse` hook installed through config is handed the base system prompt built from `prompt`, proving the hook reaches the orchestrator and is wired into the prompt pipeline rather than only being stored on the config ([validated by: hands a config-installed beforeModelResponse hook the built base system prompt, not merely storing it](../../src/config.test.ts#L108)).
- The value the hook returns then replaces the system prompt the provider receives; this is exercised at the orchestrator layer because `HalEngineConfig.provider` takes a `ProviderConfig` and offers no seam to inject a recording provider through config ([validated by: replaces system prompt with returned value](../../src/orchestration/chatOrchestrator.test.ts#L194)).
- For a session that completes without error the hooks fire in the order `beforeSession` → `beforeUserInput` → `afterUserInput` → `beforeModelResponse` → `afterModelResponse` → `afterSession` ([validated by: fires the lifecycle hooks in documented order for a session that completes without error](../../src/config.test.ts#L132)).
- `afterSession` runs after the successful turn has completed ([validated by: called after everything completes](../../src/orchestration/chatOrchestrator.test.ts#L151)).
- `beforeUserInput` receives the last user message, and its returned value is sent to the provider ([validated by: receives the last user message content](../../src/orchestration/chatOrchestrator.test.ts#L180); [validated by: modifies user message when returning different value](../../src/orchestration/chatOrchestrator.test.ts#L195)).
- `afterUserInput` receives the value returned by `beforeUserInput` ([validated by: receives user message after any beforeUserInput modification](../../src/orchestration/chatOrchestrator.test.ts#L210)).

## Engine startup

- The engine's `start()` method rejects the returned promise when it cannot bind the configured port, rather than emitting an unhandled error event that would take the process down ([validated by: rejects instead of taking the process down with an unhandled error event](../../src/config.test.ts#L174)).

## Failure semantics

These properties of `src/orchestration/chatOrchestrator.ts` specify the behaviour that hook consumers can rely on, including the failure path covered by this issue.

- `beforeSession` is inside the `try` block, so a throw there reaches the `catch`/`finally` blocks, firing both `onError` and `afterSession`, where a deployer can assume no tools were run and the turn was aborted before provider interaction ([validated by: runs onError and afterSession when beforeSession throws](../../src/orchestration/chatOrchestrator.beforeSession.acceptance.test.ts#L40); [validated by: runs error cleanup in order without contacting the provider when it throws](../../src/orchestration/chatOrchestrator.test.ts#L116)).
- The `catch` gates `onError` on `error instanceof Error` ([chatOrchestrator.ts#L150](../../src/orchestration/chatOrchestrator.ts#L150)), so a rejection that is not an `Error` — a thrown string or object — bypasses `onError` entirely while still propagating to the caller.
- A failure still propagates to the caller after `onError` runs ([validated by: error still propagates after onError hook](../../src/orchestration/chatOrchestrator.test.ts#L306)).
- `afterModelResponse` is called once per user message after the round loop exits ([chatOrchestrator.ts#L148](../../src/orchestration/chatOrchestrator.ts#L148)), and is passed the `lastUsage` local — the most recent round's usage, not a sum across tool rounds, so a deployer using the hook for billing or audit under-counts every turn that ran tools.
- The orchestrator also works when no hooks are configured ([validated by: works without any hooks configured](../../src/orchestration/chatOrchestrator.test.ts#L392)).
import {describe, expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

function createMockProvider(response: string): AIProvider {
  return {
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: response};
      yield {type: 'stop', stopReason: 'end_turn'};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({
  baseSystemPrompt: 'You are HAL.',
  systemPromptSuffix: 'Be precise.',
  contextConfig: {
    historyLength: 10,
    includeTimestamps: false,
    includeSystemPrompt: true,
  },
});

describe('beforeSession throwing', () => {
  it('runs onError and afterSession when beforeSession throws', async () => {
    const errorToThrow = new Error('Database connection failed in beforeSession');

    let caughtError: Error | undefined;
    let afterSessionRan = false;

    const orchestrator = createChatOrchestrator(createMockProvider('hello back'), promptBuilder, undefined, {
      hooks: {
        beforeSession: async () => {
          throw errorToThrow;
        },
        onError: async (_session, error) => {
          caughtError = error;
        },
        afterSession: async () => {
          afterSessionRan = true;
        },
      },
    });

    let rejectedError: unknown;
    try {
      await orchestrator.processMessage(createSession('hello'));
    } catch (error) {
      rejectedError = error;
    }

    expect({rejectedError, caughtError, afterSessionRan}).toEqual({
      rejectedError: errorToThrow,
      caughtError: errorToThrow,
      afterSessionRan: true,
    });
  });
});
